import{_ as o,o as t,c as r,ag as e}from"./chunks/framework.DzGOF12C.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"philosophy/Epistemology/04. 로크.md","filePath":"philosophy/Epistemology/04. 로크.md"}'),l={name:"philosophy/Epistemology/04. 로크.md"};function n(s,a,i,h,p,d){return t(),r("div",null,[...a[0]||(a[0]=[e('<h2 id="로크의-목적" tabindex="-1">로크의 목적 <a class="header-anchor" href="#로크의-목적" aria-label="Permalink to &quot;로크의 목적&quot;">​</a></h2><p>인간 지식의 기원, 확실성, 범위를 탐구 — 인간의 행위와 관련된 것을 알도록 돕기 위해.</p><h2 id="관념" tabindex="-1">관념 <a class="header-anchor" href="#관념" aria-label="Permalink to &quot;관념&quot;">​</a></h2><p>지성의 대상이 되는 어떤 것, 마음이 생각할 때 사용할 수 있는 모든 것 (예: 정의, 심상, 개념, 상 등). 마음 독립적인 대상이 아니라, <strong>마음 안에 있는 심적 작용의 대상</strong>이자 외부 대상 인식을 위한 매개물이라는 의미로 정의됨 (→ <strong>표상주의</strong>).</p><h2 id="본유관념-반대-논증" tabindex="-1">본유관념 반대 논증 <a class="header-anchor" href="#본유관념-반대-논증" aria-label="Permalink to &quot;본유관념 반대 논증&quot;">​</a></h2><ol><li><strong>어떤 관념에 대한 보편적 동의는 그 관념의 생득성(본유성)을 증명하지 못한다.</strong> 설령 보편적 동의가 있다는 것이 참이라 해도, 보편적 동의에 이르는 다른 방법(경험 등)이 있다면 그 동의가 본유적임을 증명할 수 없음.</li><li><strong>어떤 관념이나 원리에 대해서도 보편적 동의는 있을 수 없다.</strong> 어린아이나 백치 등에게서는 어떠한 지식의 보편적 동의도 찾아볼 수 없음 — 만약 어떤 관념이 영혼에 본래 새겨져 있다면 이들도 알고 있어야 함.</li></ol><h2 id="백지설-tabula-rasa" tabindex="-1">백지설(Tabula Rasa) <a class="header-anchor" href="#백지설-tabula-rasa" aria-label="Permalink to &quot;백지설(Tabula Rasa)&quot;">​</a></h2><p>마음이 이른바 백지라고 가정한다면, 어떻게 이 백지에 글자나 관념이 새겨지는가? → <strong>경험</strong>을 통해.</p><h2 id="지식으로서의-지위에-대한-로크의-입장" tabindex="-1">지식으로서의 지위에 대한 로크의 입장 <a class="header-anchor" href="#지식으로서의-지위에-대한-로크의-입장" aria-label="Permalink to &quot;지식으로서의 지위에 대한 로크의 입장&quot;">​</a></h2><ol><li><strong>경험론자</strong>로서 감각경험이 지식의 유일한 원천이라고 주장</li><li>로크의 관념이론은 <strong>표상주의</strong>로 나타남 — 마음은 외부 대상을 직접 인식하는 것이 아니라, 마음의 관념을 매개물로 삼아 인식함</li></ol><h2 id="측연선-plumb-line-의-비유" tabindex="-1">측연선(plumb-line)의 비유 <a class="header-anchor" href="#측연선-plumb-line-의-비유" aria-label="Permalink to &quot;측연선(plumb-line)의 비유&quot;">​</a></h2><p>측연선이란 수심을 재는 추인데, 이를 통해 바다 전체를 다 알 수는 없어도 항해사에게 큰 도움을 줌. 이처럼 마음의 힘으로 모든 사물에 대해 알 수는 없어도, 우리의 행위와 관련된 것을 아는 데는 충분히 도움이 됨.</p><h2 id="관념의-종류-및-기원-경험의-종류" tabindex="-1">관념의 종류 및 기원 (경험의 종류) <a class="header-anchor" href="#관념의-종류-및-기원-경험의-종류" aria-label="Permalink to &quot;관념의 종류 및 기원 (경험의 종류)&quot;">​</a></h2><p>관념은 <strong>외감</strong>(감각관념)과 <strong>내감</strong>(반성관념)으로 구분됨.</p><ul><li><strong>감각관념</strong>: 외부 대상에 대한 감각을 통해 얻어지는 관념</li><li><strong>반성관념</strong>: 믿음, 욕구, 상상 등 내 안에서 일어나는 자기의식 — 내 안에서 일어나는 심적 작용을 다시 지각하는 것</li></ul><p>쾌와 불쾌는 감각과 반성 양쪽 모두에서 일어날 수 있음. (→ 흄은 이러한 &#39;반성관념&#39; 개념 자체를 인정하지 않음, [[05. 흄]] 참고)</p><p>개별적 실체는 속성들의 담지자로 파악됨.</p>',17)])])}const g=o(l,[["render",n]]);export{c as __pageData,g as default};
